{"implementation":"def solve(case):
    nodes = case.get("nodes", [])
    required = set(case.get("required_symbols", []))
    by_id = {node["id"]: node for node in nodes}
    parent = {node["id"]: node.get("parent") for node in nodes}
    keep = {node["id"] for node in nodes if not node.get("removable", False)}

    for symbol in required:
        candidates = [node for node in nodes if node.get("symbol") == symbol]
        if not candidates:
            continue
        chosen = max(candidates, key=lambda node: node.get("utility", 0))
        current = chosen.get("id")
        seen = set()
        while current is not None and current not in seen:
            seen.add(current)
            keep.add(current)
            current = parent.get(current)

    retained_node_ids = [node["id"] for node in nodes if node["id"] in keep]
    removed_node_ids = [node["id"] for node in nodes if node["id"] not in keep]
    return {"removed_node_ids": removed_node_ids, "retained_node_ids": retained_node_ids}"}
